import React, { useState } from "react";

export default function NewEntry() {
  const [title, setTitle] = useState("");
  const [note, setNote] = useState("");
  const [expiry, setExpiry] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Entry Saved!\nTitle: ${title}\nNote: ${note}\nExpiry: ${expiry}`);
    setTitle("");
    setNote("");
    setExpiry("");
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-green-100 to-green-300 p-6">
      <div className="bg-white shadow-2xl rounded-2xl p-10 w-full max-w-2xl">
        <h1 className="text-3xl font-bold text-green-800 mb-6">New Entry</h1>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Title */}
          <div>
            <label className="block text-left font-medium text-gray-700">
              Title
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              className="mt-2 w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-400 focus:outline-none"
            />
          </div>

          {/* Note */}
          <div>
            <label className="block text-left font-medium text-gray-700">
              Note
            </label>
            <textarea
              rows="4"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              required
              className="mt-2 w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-400 focus:outline-none"
            />
          </div>

          {/* Expiry */}
          <div>
            <label className="block text-left font-medium text-gray-700">
              Expiry Date
            </label>
            <input
              type="date"
              value={expiry}
              onChange={(e) => setExpiry(e.target.value)}
              required
              className="mt-2 w-full p-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-400 focus:outline-none"
            />
          </div>

          {/* Submit */}
          <button
            type="submit"
            className="w-full bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-6 rounded-xl shadow-lg transition-all duration-300"
          >
            Save Entry
          </button>
        </form>
      </div>
    </div>
  );
}
